CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE farms (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT, rows INT NOT NULL, columns INT NOT NULL, panel_count INT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE panels (id BIGSERIAL PRIMARY KEY, farm_id BIGINT NOT NULL REFERENCES farms(id), panel_id VARCHAR(16) NOT NULL, row_index INT NOT NULL, column_index INT NOT NULL, string_id VARCHAR(32) NOT NULL, nominal_power_w DOUBLE PRECISION NOT NULL, efficiency_factor DOUBLE PRECISION NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(farm_id, panel_id));
CREATE TABLE telemetry (id BIGSERIAL PRIMARY KEY, panel_id BIGINT NOT NULL REFERENCES panels(id), timestamp TIMESTAMPTZ NOT NULL, vdc1 DOUBLE PRECISION NOT NULL, vdc2 DOUBLE PRECISION NOT NULL, idc1 DOUBLE PRECISION NOT NULL, idc2 DOUBLE PRECISION NOT NULL, irradiance DOUBLE PRECISION NOT NULL, pv_temperature DOUBLE PRECISION NOT NULL, actual_power_w DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE predictions (id BIGSERIAL PRIMARY KEY, panel_id BIGINT NOT NULL REFERENCES panels(id), timestamp TIMESTAMPTZ NOT NULL, actual_power_w DOUBLE PRECISION NOT NULL, expected_power_w DOUBLE PRECISION NOT NULL, deviation_w DOUBLE PRECISION NOT NULL, deviation_percent DOUBLE PRECISION NOT NULL, anomaly BOOLEAN NOT NULL, anomaly_score DOUBLE PRECISION NOT NULL, fault_type VARCHAR(64) NOT NULL, confidence DOUBLE PRECISION NOT NULL, severity VARCHAR(32) NOT NULL, model_version VARCHAR(128) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE fault_events (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(32) NOT NULL UNIQUE, panel_id BIGINT NOT NULL REFERENCES panels(id), start_time TIMESTAMPTZ NOT NULL, end_time TIMESTAMPTZ NOT NULL, fault_type VARCHAR(64) NOT NULL, severity DOUBLE PRECISION NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, panel_id BIGINT NOT NULL REFERENCES panels(id), prediction_id BIGINT NOT NULL REFERENCES predictions(id), fault_type VARCHAR(64) NOT NULL, severity VARCHAR(32) NOT NULL, message TEXT NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), acknowledged_at TIMESTAMPTZ);
CREATE TABLE model_versions (id BIGSERIAL PRIMARY KEY, model_name VARCHAR(128) NOT NULL, model_version VARCHAR(128) NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX idx_telemetry_panel_timestamp ON telemetry(panel_id, timestamp);
CREATE INDEX idx_predictions_panel_created ON predictions(panel_id, created_at);
CREATE INDEX idx_fault_events_panel_start ON fault_events(panel_id, start_time);
CREATE INDEX idx_alerts_status_created ON alerts(status, created_at);
CREATE INDEX idx_panels_farm_panel ON panels(farm_id, panel_id);
